      const v = raw === '' ? null : +raw; if (v != null && !isFinite(v)) { el.setAttribute('aria-invalid', 'true'); R('#pdHint').textContent = `${nm} must be a number.`; return; }
      if (v != null && (v < F.min || v > F.max)) { el.setAttribute('aria-invalid', 'true'); msgs.push(`${nm} must be between ${N(F.min)} and ${N(F.max)}; it counts as ${N(clamp(v, F.min, F.max), 2)}.`); } else el.removeAttribute('aria-invalid');
      if (k === 'cpc' && v === 0) msgs.push('A CPC of $0 gives no click count; enter the cost per click you expect.'); if (k === 'cvr' && v === 0) msgs.push('A click to lead rate of 0% gives no leads, so cost per lead reads n/a.');
