      R('#pdOwnTbl').innerHTML = `<div class="tblbox"><div class="tblwrap" style="max-height:340px"><table class="t"><caption class="vh">The top 25 shortlisted ZIPs at the click share wanted</caption><thead><tr><th scope="col">ZIP</th><th scope="col" class="l">City</th><th scope="col">Tier</th><th scope="col">Searches/mo</th><th scope="col">Clicks</th><th scope="col">Media/mo</th><th scope="col">Leads</th><th scope="col">Consults</th><th scope="col">Retained</th><th scope="col">Cost/retained</th><th scope="col">Value/mo</th></tr></thead><tbody>${e.slice(0, 25).map(x => `<tr><td class="name"><button type="button" class="linkbtn" data-z="${esc(x.r.zip)}">${esc(x.r.zip)}</button></td><td class="l">${esc(x.r.z.city)}</td><td>${esc(x.r.tier)}</td><td>${N(x.srch)}</td><td>${N(x.clicks, 1)}</td><td>${$$$(x.cost)}</td><td>${N(x.leads, 2)}</td><td>${N(x.cons, 2)}</td><td>${N(x.ret, 2)}</td><td>${x.ret > 0 ? $$$(x.cost / x.ret) : NA}</td><td>${$$$(x.val)}</td></tr>`).join('')}</tbody></table></div></div>`;
