    const rowsT = () => { const q = String((R('#pdFilter') || {}).value || '').trim().toLowerCase(); const all = scope(); const out = all.filter(r => !q || r.zip.startsWith(q) || String(r.z.city || '').toLowerCase().includes(q) || String(r.z.county_name || '').toLowerCase().includes(q)); const m = R('#pdFilterMsg'); if (m) m.textContent = q ? `${out.length} of ${all.length} ZIPs in scope` : `${all.length} ZIPs in scope`; return out.map(r => ({ _id: r.zip, zip: r.zip, city: r.z.city, county: r.z.county_name, tier: r.tier, quad: FLM.QN[r.quad], effb: r.effb, oppb: r.oppb, opp: r.opp, mass: r.mass, quick: r.quick, fvi: r.fvi * 100, w: r.w, comp: r.comp_pct, cpc: r.cpc_rel, bid: r.bid, angles: r.angles.map(a => (FL_ANGLES.find(x => x.id === a) || {}).short).join(', '), di: r.z.di, div: r.z.alloc.div, priv: r.z.alloc.priv, married: r.z.acs.married, inc: r.z.acs.med_hh_inc, offices: r.z.lawoffices, gt: r.z.gt })); };
