    const roll = keyOf => { const g = {}; C().rows.forEach(r => { const k = keyOf(r); if (!k) return; (g[k] = g[k] || []).push(r); }); return Object.keys(g).map(k => { const rs = g[k]; const hh = sum(rs.map(r => r.z.acs.hh || 0)); const counties = [...new Set(rs.map(r => r.z.county_name))]; return { _id: k, name: k, counties: counties.join(', '), zips: rs.length, hh, pop: sum(rs.map(r => r.z.acs.pop || 0)), mass: sum(rs.map(r => r.mass)), opp: sum(rs.map(r => r.opp)), perhh: hh > 0 ? sum(rs.map(r => r.opp)) / hh : null, eff: med(rs.map(r => r.effb)), comp: med(rs.map(r => r.comp_pct)), anchors: rs.filter(r => r.quad === 0).length, white: rs.filter(r => r.quad === 1).length }; }); };
    const coCols = [{ k: 'name', l: 'County', fmt: v => esc(v) }, { k: 'zips', l: 'ZIPs', fmt: v => N(v), d: 0 }, { k: 'opp', l: 'Fee pool', fmt: v => $$$(v), h: 'Fee pool a year ($)', d: 0 }, { k: 'perhh', l: 'Per household', fmt: v => $$$(v), h: 'Fee pool per household ($)', d: 2 }, { k: 'mass', l: 'Mass', fmt: v => N(v, 0), h: 'Matter mass a year', d: 1 }, { k: 'eff', l: 'Median eff.', fmt: v => N(v, 0), h: 'Median efficiency percentile', d: 1 }, { k: 'comp', l: 'Median comp.', fmt: v => N(v, 0), h: 'Median competition percentile', d: 1 }, { k: 'anchors', l: 'Anchor', fmt: v => N(v), d: 0 }, { k: 'white', l: 'Whitespace', fmt: v => N(v), d: 0 }];
    const ciCols = [{ k: 'name', l: 'City', fmt: v => esc(v) }, { k: 'counties', l: 'County', fmt: v => esc(v), cls: 'l' }, { k: 'zips', l: 'ZIPs', fmt: v => N(v), d: 0 }, { k: 'pop', l: 'Population', fmt: v => N(v), d: 0 }, { k: 'opp', l: 'Fee pool', fmt: v => $$$(v), h: 'Fee pool a year ($)', d: 0 }, { k: 'perhh', l: 'Per household', fmt: v => $$$(v), h: 'Fee pool per household ($)', d: 2 }, { k: 'eff', l: 'Median eff.', fmt: v => N(v, 0), h: 'Median efficiency percentile', d: 1 }, { k: 'anchors', l: 'Anchor', fmt: v => N(v), d: 0 }, { k: 'white', l: 'Whitespace', fmt: v => N(v), d: 0 }];
