    R('#pdGoogle').onclick = () => { const s = short(); R('#pdExpMsg').textContent = `Google Ads locations: the top ${s.length} ZIPs by ${PD_RANK[st.rank].l.toLowerCase()} with their tier bid modifiers, campaign ${campName()}.${noIdMsg(s)}`; exportText(expName('paid_google_locations', geoScope()), csv(s.map(r => ({ camp: campName(), loc: r.zip + ', Texas, United States', id: r.z.gt || '', bid: (r.bid > 0 ? '+' : '') + r.bid + '%', type: 'Location', status: 'Enabled' })), [{ l: 'Campaign', k: 'camp' }, { l: 'Location', k: 'loc' }, { l: 'ID', k: 'id' }, { l: 'Bid Modifier', k: 'bid' }, { l: 'Criterion Type', k: 'type' }, { l: 'Status', k: 'status' }], { platform: true })); };
