    R('#pdAll').onclick = () => exportText(expName('paid_zips', geoScope()), csv(tbl.sorted(), xcols(cols)));
    R('#pdCoX').onclick = () => exportText(expName('paid_county_rollup', geo()), csv(coT.sorted(), xcols(coCols)));
