    R('#pdAsm').onclick = () => exportText(expName('paid_assumptions', geoScope(), 'json'), JSON.stringify({ module: 'Paid Acquisition (07)', exported: todayISO(), metro: { code: st.metro, name: geo() }, scope: { county: st.cty || null, quadrant: st.quad === '' ? null : FLM.QN[+st.quad], angle: st.angle || null }, line: { key: st.line, name: LINE_META[st.line].name }, shortlist: { rank_by: PD_RANK[st.rank].l, size: st.n, zips: short().map(r => ({ zip: r.zip, tier: r.tier, bid: r.bid })) }, metro_searches_a_month: { value: Math.round(srch()), source: isN(st.searches[st.metro]) ? 'your input' : 'default (grade D): ' + SEV_MODEL.rate('searchPerFiling') + ' a month per private family filing a year' }, model: SEV_MODEL.snapshot(), method: { payer_weight: 'payLow under $35,000, payMid $35,000 to $60,000, 1 above', fee_value_index: 'sqrt(ZIP median household income / metro median), 0.7 to 1.6', click_cost_index: '0.55 + 1.55 x (0.6 competition pct + 0.4 value pct)', blend: '65/35 with the radius sum', quadrant: 'opportunity 65th, competition 60th percentile', tiers: FLM.TIERS.map((t, i) => ({ tier: t, from_pct: Math.max(0, FLM.TIER_CUT[i]), bid_pct: FLM.TIER_BID[i] })) }, sources: { cpc: 'median legal services CPC, Google search, Apr 2025 to Mar 2026 (WordStream)', conversion: 'median legal conversion 5.55%; family law 8.52% in the 2023 LocaliQ cut', filings: 'county filings (Texas OCA, ' + ttmSpan() + ') allocated to ZIPs by married adults times the modeled hazard', offices: 'ZIP Business Patterns 2023' } }, null, 2), 'application/json');
